<?php
require_once __DIR__ . '/partials.php';
require_once __DIR__ . '/api/duffel.php';
function fr_h(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}
function fr_valid_date(string $d):bool{$x=DateTime::createFromFormat('Y-m-d',$d);return $x&&$x->format('Y-m-d')===$d;}
function fr_time(?string $d):string{$t=$d?strtotime($d):false;return $t?date('H:i',$t):'';}
function fr_day(?string $d):string{$t=$d?strtotime($d):false;return $t?date('D, d M',$t):'';}
function fr_minutes(?string $d):int{if(!$d)return 0;try{$x=new DateInterval($d);return $x->d*1440+$x->h*60+$x->i;}catch(Throwable $e){return 0;}}
function fr_duration(?string $d):string{$m=fr_minutes($d);return $m?(intdiv($m,60).'h '.($m%60).'m'):'';}
function fr_offer_duration(array $o):int{$n=0;foreach(($o['slices']??[]) as $s)$n+=fr_minutes($s['duration']??null);return $n;}
function fr_max_stops(array $o):int{$m=0;foreach(($o['slices']??[]) as $s)$m=max($m,max(0,count($s['segments']??[])-1));return $m;}
function fr_airline(array $o):string{if(!empty($o['owner']['name']))return(string)$o['owner']['name'];foreach(($o['slices']??[])as$s)foreach(($s['segments']??[])as$g)if(!empty($g['marketing_carrier']['name']))return(string)$g['marketing_carrier']['name'];return'Airline';}
function fr_logo(array $o):string{return(string)($o['owner']['logo_symbol_url']??$o['owner']['logo_lockup_url']??'');}
function fr_operating(array $o):array{$a=[];foreach(($o['slices']??[])as$s)foreach(($s['segments']??[])as$g){$n=trim((string)($g['operating_carrier']['name']??''));if($n)$a[]=$n;}return array_values(array_unique($a));}
function fr_checked_bags(array $o):int{$q=0;foreach(($o['slices']??[])as$s)foreach(($s['segments']??[])as$g)foreach(($g['passengers']??[])as$p)foreach(($p['baggages']??[])as$b)if(($b['type']??'')==='checked')$q=max($q,(int)($b['quantity']??0));return$q;}
function fr_cabin_bags(array $o):int{$q=0;foreach(($o['slices']??[])as$s)foreach(($s['segments']??[])as$g)foreach(($g['passengers']??[])as$p)foreach(($p['baggages']??[])as$b)if(in_array(($b['type']??''),['carry_on','cabin'],true))$q=max($q,(int)($b['quantity']??0));return$q;}
function fr_hold(array $o):bool{return(($o['payment_requirements']['requires_instant_payment']??true)===false);}
function fr_stops(array $s):array{$g=$s['segments']??[];$a=[];for($i=0;$i<count($g)-1;$i++){if($c=$g[$i]['destination']['iata_code']??'')$a[]=$c;}return$a;}
$criteria=['trip_type'=>(($_GET['trip_type']??'round')==='oneway'?'oneway':'round'),'origin'=>strtoupper(trim($_GET['origin']??'')),'destination'=>strtoupper(trim($_GET['destination']??'')),'departure'=>trim($_GET['departure']??''),'return_date'=>trim($_GET['return_date']??''),'adults'=>max(1,min(9,(int)($_GET['adults']??1))),'children'=>max(0,min(8,(int)($_GET['children']??0))),'infants'=>max(0,min(9,(int)($_GET['infants']??0))),'cabin'=>trim($_GET['cabin']??'economy')];
$error='';$offers=[];$allowed=['economy','premium_economy','business','first'];
if(!preg_match('/^[A-Z]{3}$/',$criteria['origin']))$error='Invalid origin airport.';
elseif(!preg_match('/^[A-Z]{3}$/',$criteria['destination']))$error='Invalid destination airport.';
elseif($criteria['origin']===$criteria['destination'])$error='Origin and destination cannot be the same.';
elseif(!fr_valid_date($criteria['departure'])||$criteria['departure']<date('Y-m-d'))$error='Invalid departure date.';
elseif($criteria['trip_type']==='round'&&(!fr_valid_date($criteria['return_date'])||$criteria['return_date']<$criteria['departure']))$error='Invalid return date.';
elseif($criteria['infants']>$criteria['adults'])$error='Infants cannot exceed adults.';
elseif(!in_array($criteria['cabin'],$allowed,true))$error='Invalid cabin class.';
else{$api=mt_duffel_search($criteria);if(!$api['ok']){$error=$api['error'];error_log('FLIGHT RESULTS DUFFEL | HTTP '.$api['status'].' | '.json_encode($api['data']));}else{$offers=$api['data']['data']['offers']??[];if(!is_array($offers))$offers=[];$offers=array_slice($offers,0,50);}}
$airlines=[];$minPrice=null;$maxPrice=0;foreach($offers as$o){$airlines[]=fr_airline($o);$p=(float)($o['total_amount']??0);if($p>0){$minPrice=$minPrice===null?$p:min($minPrice,$p);$maxPrice=max($maxPrice,$p);}}$airlines=array_values(array_unique($airlines));sort($airlines);
site_header('Flight Results');
?>
