<script>
document.addEventListener('DOMContentLoaded',()=>{const w=document.getElementById('cards');if(!w)return;const cards=[...w.querySelectorAll('.fr-card')],count=document.getElementById('visibleCount');
function filter(){let stop=document.querySelector('input[name="stopFilter"]:checked')?.value||'any',air=document.getElementById('airlineFilter').value,bag=document.getElementById('bagFilter').checked,hold=document.getElementById('holdFilter').checked,text=document.getElementById('textFilter').value.trim().toLowerCase(),n=0;cards.forEach(c=>{let ok=true,s=parseInt(c.dataset.stops);if(stop!=='any'&&s>parseInt(stop))ok=false;if(air&&c.dataset.airline!==air)ok=false;if(bag&&c.dataset.bag!=='1')ok=false;if(hold&&c.dataset.hold!=='1')ok=false;if(text&&!c.dataset.search.includes(text))ok=false;c.style.display=ok?'':'none';if(ok)n++;});count.textContent=n;}
document.querySelectorAll('input[name="stopFilter"]').forEach(x=>x.onchange=filter);airlineFilter.onchange=filter;bagFilter.onchange=filter;holdFilter.onchange=filter;textFilter.oninput=filter;resetFilters.onclick=()=>{document.querySelector('input[name="stopFilter"][value="any"]').checked=true;airlineFilter.value='';bagFilter.checked=false;holdFilter.checked=false;textFilter.value='';filter();};
function sort(type){[...cards].sort((a,b)=>parseFloat(a.dataset[type==='price'?'price':type==='duration'?'duration':'best'])-parseFloat(b.dataset[type==='price'?'price':type==='duration'?'duration':'best'])).forEach(c=>w.appendChild(c));document.querySelectorAll('.fr-sort').forEach(b=>b.classList.toggle('active',b.dataset.sort===type));}document.querySelectorAll('.fr-sort').forEach(b=>b.onclick=()=>sort(b.dataset.sort));sort('best');});
</script>
